(function(root){
'use strict';
const local=typeof module!=='undefined'&&module.exports,G=local?require('./growth.js'):root.LGAGrowth,C=local?require('./core.js'):root.LGACore,I=local?require('./i18n.js'):root.LGAI18n,e=x=>I?I.value(x):C.esc(x);
const btn=(action,label,attrs='',cls='')=>`<button type="button" data-action="${action}" class="${cls}" ${attrs}>${label}</button>`;
const folderIcon='<svg class="map-folder-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7Z"/></svg>';
const menuLabel=title=>`<span class="map-node-label">${folderIcon}<strong>${e(title)}</strong></span>`;
const foot=html=>`<div class="card-actions">${html}</div>`;
const fieldError=(id,name)=>`<p id="${id}-error" class="map-field-error" data-field-error="${name}" role="alert" hidden></p>`;

// The same menu-shaped map is used for a candidate and the customer's editable copy.
function menuState(nodes,c={}){
 const mode=['all','collapsed','auto'].includes(c.mapExpansion)?c.mapExpansion:'configured';
 const branches=nodes.filter(n=>nodes.some(x=>x.parent===n.id)).map(n=>n.id);
 let open=Array.isArray(c.mapOpenIds)?c.mapOpenIds.filter(id=>branches.includes(id)):null;
 if(!open){
  open=mode==='all'?[...branches]:mode==='configured'?branches.filter(id=>{let root=nodes.find(n=>n.id===id);while(root.parent)root=nodes.find(n=>n.id===root.parent);return root.navPlacement!=='footer'||root.footerExpanded;}):[];
  if(mode==='auto'){
   let node=nodes.find(n=>n.id===(c.mapEditor==='add'?c.mapAddParent:c.mapNodeId));const selected=!!node;
   while(node){if(branches.includes(node.id))open.push(node.id);node=nodes.find(n=>n.id===node.parent);}
   if(!selected&&branches.length)open=[branches[0]];
  }
 }
 return {mode,open,branches};
}
function settings(n,t){return btn('openMapNode','<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 4 6 6M3 21l2-7L16 3a2.8 2.8 0 0 1 4 4L9 18Z"/></svg>',`data-id="${e(n.id)}" aria-label="${t('栏目设置','Page settings')} ${e(n.title)}" title="${t('栏目设置','Page settings')}"`,'map-node-settings');}
function menuMap(nodes,node,t,brand,c={}){
 const label=n=>n.titleEn?t(n.title,n.titleEn):n.title,{mode,open,branches}=menuState(nodes,c);
 const detailLinks=n=>c.detailState?'<ul class="map-menu-details">'+(local?require('./self-website.js'):root.LGASelfWebsite).detailsFor(c.detailState,n.id).filter(b=>b.body?.trim()).map(b=>'<li>'+btn('editSiteBlock',e(b.title),'data-id="'+e(b.id)+'" title="'+e(b.title)+'"')+(local?require('./self-website.js'):root.LGASelfWebsite).mountIcon(b)+'</li>').join('')+'</ul>':'';
 const item=n=>{
  const children=nodes.filter(x=>x.parent===n.id);
  if(c.contentIndex)return `<section class="content-map-branch" data-content-page="${e(n.id)}">${node(n)}${children.length?`<div class="map-dropdown"><ul>${children.map(child=>`<li>${item(child)}</li>`).join('')}</ul></div>`:''}</section>`;
  if(!children.length)return node(n)+detailLinks(n);
  const selected=c.mapNodeId===n.id&&c.mapEditor!=='add';
  const title=`<span>${menuLabel(label(n))}${n.visible?'':`<small>${t('已隐藏','Hidden')}</small>`}</span>`;
  const select=c.mapEditable?`<span class="map-menu-title">${btn('openMapNode',title,`data-id="${e(n.id)}" title="${t('修改栏目设置','Edit page settings')}"`,'map-page-link')}${settings(n,t)}</span>`:`<span class="map-menu-title">${title}</span>`;
  return `<details class="map-menu" ${open.includes(n.id)?'open':''} data-map-id="${e(n.id)}" data-map-parent="${e(n.parent)}"><summary data-selected="${selected}" title="${t('展开或收起下级栏目','Expand or collapse child pages')}">${select}</summary>${detailLinks(n)}<div class="map-dropdown"><ul>${children.map(child=>`<li>${item(child)}</li>`).join('')}</ul></div></details>`;
 };
 const selected=id=>id==='auto'?mode==='auto':mode!=='auto'&&(id==='all'?open.length===branches.length:open.length===0);
 const controls=[['collapsed',t('全收缩','Collapse all')],['all',t('全展开','Expand all')],['auto',t('自动收展','Auto expand')]].map(([id,label])=>btn('mapExpansion',label,`data-mode="${id}" aria-pressed="${selected(id)}"${id==='auto'?` title="${t('打开一个分支时，自动收起其他分支','Opening a branch collapses other branches')}"`:''}`)).join('');
 return `<div class="map-browser" data-map-expansion="${mode}"><div class="map-browser-bar"><strong>${e(brand)}</strong><div class="map-expansion-controls" role="group" aria-label="${t('架构展开方式','Structure expansion')}">${c.contentIndex?'':controls}</div></div><div class="map-position-groups">${[['header','页头菜单'],['footer','页脚菜单']].map(([position,title])=>`<section class="map-position-group"><h3>${title}</h3><nav class="map-navigation" tabindex="0" aria-label="${title}"><ul class="map-primary">${nodes.filter(n=>!n.parent&&(n.navPlacement||'header')===position).map(n=>`<li class="map-menu-column${nodes.some(x=>x.parent===n.id)?'':' map-menu-leaf'}">${item(n)}</li>`).join('')}</ul></nav></section>`).join('')}</div></div>`;
}
function editor(s,c,t){
 const m=G.map(s),n=m.nodes.find(n=>n.id===c.mapNodeId),adding=c.mapEditor==='add';
 if(!adding&&!n)return `<p class="map-edit-prompt">${t('点栏目名称或铅笔，修改栏目名称、层级和显示设置。','Click a page name or pencil to edit its name, hierarchy and display settings.')}</p>`;
 const label=n=>n.titleEn?t(n.title,n.titleEn):n.title;
 const breadcrumb=n=>{const names=[label(n)];while(n.parent){n=m.nodes.find(x=>x.id===n.parent);names.unshift(label(n));}return names.join(' / ');};
 const parents=(id,selected)=>`<option value="" ${!selected?'selected':''}>${t('一级菜单','Top-level menu')}</option>${G.parentOptions(m.nodes,id).map(x=>`<option value="${e(x.id)}" ${selected===x.id?'selected':''}>${e((local?require('./self-website.js'):root.LGASelfWebsite).menuLabel(s,x))}</option>`).join('')}`;
 const placement=n=>`<div class="map-placement-field" ${n?.parent?'hidden':''}><label>显示位置</label><select name="navPlacement"><option value="header" ${n?.navPlacement!=='footer'?'selected':''}>页头</option><option value="footer" ${n?.navPlacement==='footer'?'selected':''}>页脚</option></select></div><label class="menu-expanded-choice" ${n?.parent||n?.navPlacement!=='footer'?'hidden':''}><input name="footerExpanded" type="checkbox" ${n?.footerExpanded?'checked':''}>默认展开</label>`;
 const end=btn('closeMapEditor',t('收起编辑','Close editor'));
 if(adding)return `<section class="map-properties" aria-labelledby="map-properties-title"><h3 id="map-properties-title">${c.mapAddParent?t('添加下级栏目','Add a child page'):t('添加一级菜单','Add a top-level menu')}</h3><form data-form="sitemapAdd"><div class="grid2"><div><label for="map-new-title">${t('栏目名称','Page title')}</label><input id="map-new-title" name="title" aria-describedby="map-new-title-error" required>${fieldError("map-new-title","title")}</div><div><label for="map-new-parent">${t('放在哪个菜单下？','Parent menu')}</label><select id="map-new-parent" name="parent">${parents('',c.mapAddParent||'')}</select></div>${placement({parent:c.mapAddParent})}</div>${foot(end+'<button class="primary">'+t('添加栏目','Add page')+'</button>')}</form></section>`;
 const W=local?require('./self-website.js'):root.LGASelfWebsite,presentation=W.config(s,n.id);
 const display=`<fieldset class="map-display-settings"><legend>${t('栏目显示设置','Page display settings')}</legend><div class="grid2"><div><label for="map-mode-${e(n.id)}">${t('显示方式','Display mode')}</label><select id="map-mode-${e(n.id)}" name="displayMode"><option value="">${t('请选择','Choose')}</option>${Object.entries(W.modes).map(([id,name])=>`<option value="${id}" ${presentation.mode===id?'selected':''}>${t(name,({list:'List',tabs:'Tabs',carousel:'Carousel'})[id])}</option>`).join('')}</select></div><div><label for="map-pagination-${e(n.id)}">${t('分页','Pagination')}</label><select id="map-pagination-${e(n.id)}" name="pagination"><option value="off" ${!presentation.pagination?'selected':''}>${t('不分页','No pagination')}</option><option value="on" ${presentation.pagination?'selected':''}>${t('分页','Paginate')}</option></select></div><div><label for="map-size-${e(n.id)}">${t('每页显示数量','Items per page')}</label><input id="map-size-${e(n.id)}" name="pageSize" type="number" min="1" max="100" required value="${presentation.pageSize}"></div></div></fieldset>`;
 const moves=G.sitemapMoveTargets(m.nodes,n.id);
 let depth=1,parent=n;while(parent.parent){depth++;parent=m.nodes.find(x=>x.id===parent.parent);}
 const parentSelect=n.id==='hero'?'<input type="hidden" name="parent" value="">':`<label for="map-parent-${n.id}">${t('放在哪个菜单下？','Parent menu')}</label><select id="map-parent-${n.id}" name="parent">${parents(n.id,n.parent)}</select>`;
 return `<section class="map-properties" aria-labelledby="map-properties-title"><div class="between"><h3 id="map-properties-title">${t('编辑栏目','Edit page')} · ${e(label(n))}</h3><span class="small muted">${e(breadcrumb(n))}</span></div><form data-form="sitemapNode"><input type="hidden" name="id" value="${e(n.id)}"><div class="grid2"><div><label for="map-title-${n.id}">${t('栏目名称','Page title')}</label><input id="map-title-${n.id}" name="title" value="${e(n.title)}" aria-describedby="map-title-${n.id}-error" required>${fieldError("map-title-"+n.id,"title")}</div><div>${parentSelect}</div>${placement(n)}</div>${display}${foot((n.id!=='hero'&&depth<3?btn('addMapPage',t('添加下级栏目','Add child page'),`data-parent="${n.id}"`):'')+(!['hero','contact'].includes(n.id)?btn('removeSitemapNode',t('移除栏目','Remove page'),`data-id="${n.id}"`):'')+(n.id!=='hero'?btn('moveSitemapNode',n.parent?t('上移','Move up'):t('前移','Move earlier'),`data-id="${n.id}" data-direction="up" ${moves.up?'':`disabled title="${t('已是同级第一个可移动栏目','Already the first movable page at this level')}"`}`)+btn('moveSitemapNode',n.parent?t('下移','Move down'):t('后移','Move later'),`data-id="${n.id}" data-direction="down" ${moves.down?'':`disabled title="${t('已是同级最后一个栏目','Already the last page at this level')}"`}`):'')+end+'<button class="primary">'+t('保存栏目','Save page')+'</button>')}</form></section>`;
}
function overview(s,c={}){
 const t=(zh,en)=>c.language==='en'?en:zh,m=G.map(s),adopted=!!m.nodes.length;
 const template=G.templateById(m.template)||G.templateById(G.recommendation(s).template)||G.templates[0];
 const nodes=adopted?m.nodes:G.mapNodes(template.id),label=n=>c.language==='en'&&n.titleEn?n.titleEn:n.title;
 const node=n=>`<span class="map-leaf-row"><button type="button" class="map-overview-node ${n.visible?'':'is-hidden'}" aria-pressed="${c.mapNodeId===n.id&&c.mapEditor!=='add'}" data-action="${adopted?'openMapNode':'previewSitemap'}" data-id="${e(adopted?n.id:template.id)}">${menuLabel(label(n))}${n.visible?'':`<small>${t('已隐藏','Hidden')}</small>`}</button>${adopted?settings(n,t):''}</span>`;
 const pending=adopted&&s.site.sitemap?.appliedRevision!==m.revision;
 return `<section class="card site-map-overview" aria-labelledby="site-map-overview-title"><div class="between"><div><h2 id="site-map-overview-title">${t('网站架构','Website structure')}</h2><p>${t('点栏目名称或铅笔修改架构与显示设置；箭头展开下级。','Click a page name or pencil to edit structure and display settings; arrows expand child pages.')}</p></div><div class="inline"><span class="tag">${e(m.template==='existing-website'?t('已有网站', 'Existing website'):t(template.zh,template.en))}${adopted?' · v'+m.revision:''}</span>${adopted?btn('addMapPage',t('添加一级菜单','Add a top-level menu')):''}${btn('sitemapPanel',t('更换网站架构','Change website structure'),'data-panel="catalog"')}${btn('openWebsiteImport',t('从已有网站读取','Read existing website'))}</div></div>${m.template==='existing-website'&&s.site.imported?`<p class="small muted">${e(s.site.imported.source)} · ${s.site.imported.details?t('已读入各页明细，可在内容详情中修改','Page content imported; edit it in Content details'):t('仅架构，明细待填写','Structure only; page content can be added next')}</p>${s.site.imported.failures.length?`<details><summary>${s.site.imported.failures.length} ${t('页明细未读到','pages could not be read')}</summary><p>${s.site.imported.failures.map(f=>e(f.title)+'：'+e(f.reason)).join(' · ')}</p></details>`:''}`:''}${menuMap(nodes,node,t,s.company.draft.name,{...c,mapEditable:adopted,detailState:adopted?s:null})}${adopted?editor(s,c,t):''}<p class="small muted">${pending?t('栏目已保存，继续后更新网站草稿。','Pages are saved. Continue to update the website draft.'):t('保存栏目即更新网站草稿。可继续修改，或直接选择网站风格。','Saving a page updates the website draft. Continue editing or choose an appearance.')}</p>${foot(adopted?btn('buildSitemap',t('下一步：网站风格','Next: website appearance'),'','primary'):btn('selectSitemap',t('采用为我的网站架构','Use as my website structure'),`data-id="${template.id}"`,'primary'))}</section>`;
}
function render(s,c,t){
 const m=G.map(s),catalog=G.catalog,template=G.templateById(c.sitemapPreview)||G.templateById(m.template)||G.templateById(G.recommendation(s).template)||G.templates[0];
 const panel=['catalog','preview','edit'].includes(c.sitemapPanel)?c.sitemapPanel:(m.nodes.length?'edit':'catalog'),group=c.sitemapGroup||'all',query=c.sitemapQuery||'',matched=new Set(catalog.search(query,group).map(x=>x.id));
 const label=n=>n.titleEn?t(n.title,n.titleEn):n.title;
 let html=`<div id="sitemap-panel" class="sitemap-workspace">`;
 if(panel==='catalog'){
  html+=`<section class="card"><div class="between"><div><h2>${t('选择适合你行业的网站架构','Choose a structure for your industry')}</h2><p>${t('模板和已有站点读入均最多支持三级菜单；采用后可手动增删、改名和排序。','Plan your pages here. Choose their appearance in the following step.')}</p></div>${btn('openWebsiteImport',t('从已有网站读取','Read existing website'))}</div><div class="grid2"><div><label for="sitemap-search">${t('搜索行业、产品或栏目','Search industry, product or page')}</label><input type="search" id="sitemap-search" data-sitemap-search value="${e(query)}" placeholder="${t('例如：机械、食品、物流、OEM、software','For example: machinery, food, logistics, OEM, software')}"></div><div><label for="sitemap-group">${t('行业分类','Industry group')}</label><select id="sitemap-group" data-sitemap-group><option value="all">${t('全部行业','All industries')}</option>${catalog.groups.map(g=>`<option value="${g.id}" ${g.id===group?'selected':''}>${e(t(g.zh,g.en))}</option>`).join('')}</select></div></div><p class="small muted" data-sitemap-count role="status">${matched.size} / ${G.templates.length} ${t('套架构','structures')}</p><div class="industry-grid">${G.templates.map(x=>{
   const nodes=G.mapNodes(x.id),top=nodes.filter(n=>!n.parent&&n.id!=='hero'&&n.id!=='contact');
   return `<article class="industry-card" data-sitemap-card="${x.id}" ${matched.has(x.id)?'':'hidden'}><div class="between"><span class="eyebrow">${x.code}</span>${m.template===x.id?`<span class="tag">${t('当前采用','In use')}</span>`:''}</div><h3>${e(t(x.zh,x.en))}</h3><p>${e(t(x.why,x.whyEn))}</p><ol class="industry-menu">${top.map(n=>`<li><span>${e(label(n))}</span><small>${nodes.filter(y=>y.parent===n.id).length?`${nodes.filter(y=>y.parent===n.id).length} ${t('个下级页','child pages')}`:''}</small></li>`).join('')}</ol>${foot(btn('previewSitemap',t('查看这套结构','Preview structure'),`data-id="${x.id}"`,'primary'))}</article>`;
  }).join('')}</div><p class="empty" data-sitemap-empty ${matched.size?'hidden':''}>${t('没有找到匹配架构。换个关键词，或先采用相近行业再修改栏目。','No matching structure. Try another term, or start with a related industry and edit its pages.')}</p><details><summary>${t('参考来源与设计说明','Reference sources and design notes')}</summary><p>${t('参考华为云、阿里云建站公开行业分类与样例线索，具体栏目为 LGA 设计。不是官方模板原件，不包含其素材或代码。','Based on public Huawei Cloud and Alibaba Cloud industry categories and example clues. LGA designed these structures; they are not official template files or copied assets.')}</p>${catalog.sources.map(x=>`<p><a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(t(x.name,x.nameEn))}</a> · ${e(t(x.scope,x.scopeEn))}</p>`).join('')}</details></section>`;
 }else if(panel==='preview'){
  const nodes=G.mapNodes(template.id),same=m.template===template.id&&m.nodes.length;
  const node=n=>`<div class="map-overview-node">${menuLabel(label(n))}<small>${e(n.path)}</small><span>${t('模板栏目','Template page')}</span></div>`;
  html+=`<section class="card sitemap-preview"><div class="between"><div><p class="eyebrow">${e(template.code||t('旧版结构','Previous structure'))}</p><h2>${e(t(template.zh,template.en))}</h2><p>${e(t(template.why,template.whyEn))}</p></div><span class="tag">${t('架构预览','Structure preview')}</span></div>${menuMap(nodes,node,t,s.company.draft.name,c)}<div class="hint"><strong>${t('把这套菜单改成你自己的','Make this menu your own')}</strong><p>${same?t('你已采用这套架构。继续编辑会保留你修改过的名称、顺序和页面。','You already use this structure. Continue editing to keep your names, order and pages.'):t('采用后，点击栏目改名、增删下级、调整顺序；再按此架构准备网站，逐页补入你自己的内容。','Adopt it, then click pages to rename, add children or reorder. Prepare the website from your structure and fill each section with your content.')}</p></div>${template.category?`<details><summary>${t('行业参考依据','Industry reference')}</summary><p>${e(t(template.category,template.categoryEn))}</p><p>${t('参考公开行业分类，菜单为 LGA 设计建议。页面形式在网站风格中选择，默认多页面。','Based on public industry categories; menus are designed by LGA. Choose the page format in website appearance. Multiple pages is the default.')}</p></details>`:''}${foot(btn('sitemapPanel',t('返回行业列表','Back to industries'),'data-panel="catalog"')+btn('selectSitemap',same?t('继续编辑我的架构','Continue editing my structure'):t('采用为我的网站架构','Use as my website structure'),`data-id="${template.id}"`,'primary'))}</section>`;
 }else if(!m.nodes.length){
  html+=`<section class="card"><h2>${t('先选择一个接近你业务的架构','Choose a structure close to your business')}</h2><p>${t('采用后，每个栏目都能继续修改。','You can edit each page after selecting a structure.')}</p>${foot(btn('sitemapPanel',t('选择行业架构','Choose an industry'),'data-panel="catalog"','primary'))}</section>`;
 }else{
  html+=overview(s,c);
 }
 return html+'</div>'+(c.websiteImportOpen?`<dialog id="website-import-dialog" class="website-import-dialog" aria-labelledby="website-import-heading"><header><div class="website-import-heading"><h2 id="website-import-heading">${t('从已有网站读取','Read existing website')}</h2><p class="small muted">${t('先检查读取结果，再采用；之后可人工或 AI 编辑。','Review before applying; then edit manually or with AI.')}</p></div>${btn('closeWebsiteImport','×','aria-label="关闭读取窗口"')}</header><form id="website-import-form" class="website-import-form" data-form="websiteImport">
 <div class="website-import-fields"><label for="website-import-url">${t('已有网站网址','Existing website URL')}<input type="url" id="website-import-url" name="url" value="${e(s.site.reference||s.site.start?.reference||'')}" placeholder="https://www.example.com/" required></label></div>
 <div class="website-import-options"><label class="website-import-scope" for="website-import-scope">${t('读取范围','Import scope')}<select id="website-import-scope" name="scope"><option value="structure">${t('仅架构','Structure only')}</option><option value="details" selected>${t('架构 + 明细','Structure + content')}</option></select></label><div class="website-import-media"><label><input name="images" type="checkbox" checked>读取图片</label><label><input name="videos" type="checkbox" checked>读取视频</label><span class="small muted">未读取的媒体保留占位，可在详情中替换。</span></div></div>
 <p data-website-import-progress role="status"></p><div class="website-import-result" data-website-import-result hidden></div>
 </form><footer class="website-import-actions">${btn('closeWebsiteImport',t('取消','Cancel'))}<button type="submit" form="website-import-form">${t('读取网站','Read website')}</button><button type="button" class="primary" data-action="applyWebsiteImport" hidden>${t('采用读取结果','Apply import')}</button></footer></dialog>`:'');
}
if(local)module.exports={render,overview,menuMap,menuState,folderIcon};else root.LGASitemapView={render,overview,menuMap,menuState,folderIcon};
})(typeof globalThis!=='undefined'?globalThis:this);
